-- All 9 brand logos somehow got cleared (logo_url set to null) between
-- sessions. Restores each one to its last-known-good version, reconstructed
-- from the migration history still in git (plus one regenerated from its
-- original source file, since that particular fix was only ever applied via
-- a pasted chat SQL snippet, never committed as a migration).

update brands set logo_url = 'data:image/png;base64,' where name = 'K18';

update brands set logo_url = 'data:image/png;base64,' where name = 'Color Wow';

update brands set logo_url = 'data:image/png;base64,' where name = 'KEVIN.MURPHY';

update brands set logo_url = 'data:image/png;base64,' where name = 'Davines';

update brands set logo_url = 'data:image/png;base64,' where name = 'Living Proof';

update brands set logo_url = 'data:image/png;base64,' where name = 'Eleven Australia';

update brands set logo_url = 'data:image/png;base64,' where name = 'Aveda';

update brands set logo_url = 'data:image/jpeg;base64,' where name = 'Eleven Australia Colour';

update brands set logo_url = 'data:image/png;base64,' where name = 'KEVIN.MURPHY Colour';
